@import "@fontsource-variable/dm-sans";
@import "@fontsource-variable/newsreader";
@import "@fontsource/dm-mono/400.css";

/* Light (faithful): white page, #f0f0f0 panels and light buttons, #dedede hairlines and
   inactive cards, black ink, #626262 secondary text, #1d1d1d dark buttons, a deep purple
   (#450e78) only for small figure badges and chart dots. */
:root {
  --background: #ffffff;
  --foreground: #000000;
  --card: #ffffff;
  --card-foreground: #000000;
  --popover: #ffffff;
  --popover-foreground: #000000;
  --primary: #1d1d1d;
  --primary-foreground: #ffffff;
  --secondary: #f0f0f0;
  --secondary-foreground: #000000;
  --muted: #f0f0f0;
  --muted-foreground: #626262;
  --accent: #dedede;
  --accent-foreground: #000000;
  --destructive: #c4302b;
  --destructive-foreground: #ffffff;
  --border: #dedede;
  --input: #dedede;
  --ring: #818181;
  --highlight: #450e78;
  --highlight-foreground: #ffffff;
  --glow: #181818;
  --chart-1: #a35cf0;
  --chart-2: #4f77d8;
  --chart-3: #b8cdf6;
  --chart-4: #1f8f5a;
  --chart-5: #f0b429;
  --sidebar: #f0f0f0;
  --sidebar-foreground: #000000;
  --sidebar-primary: #1d1d1d;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #dedede;
  --sidebar-accent-foreground: #000000;
  --sidebar-border: #dedede;
  --sidebar-ring: #818181;

  --typeface-body: "DM Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "DM Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "DM Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  /* paragraphs and figures: ondo blocks read var(--ondo-serif, var(--typeface-display)) */
  --ondo-serif: "Newsreader Variable", ui-serif, Georgia, serif;
  --radius: 0.5rem;
  --page-width: 90rem;
  --page-gutter: 1rem;
  --section-y: 5rem;
}

/* Dark sibling, and the colours of the original's black bands: pure black page, #0d0d0d
   cards behind white hairlines at 12%, #313131 raised panels, light #f0f0f0 buttons. */
.dark {
  --background: #000000;
  --foreground: #ffffff;
  --card: #0d0d0d;
  --card-foreground: #ffffff;
  --popover: #1d1d1d;
  --popover-foreground: #ffffff;
  --primary: #f0f0f0;
  --primary-foreground: #000000;
  --secondary: #313131;
  --secondary-foreground: #ffffff;
  --muted: #1d1d1d;
  --muted-foreground: #8f8f8f;
  --accent: #313131;
  --accent-foreground: #ffffff;
  --destructive: #e5534b;
  --destructive-foreground: #ffffff;
  --border: rgb(255 255 255 / 12%);
  --input: rgb(255 255 255 / 18%);
  --ring: #b1b1b1;
  --highlight: #c9a3ff;
  --highlight-foreground: #000000;
  --glow: #000000;
  --chart-1: #b57bff;
  --chart-2: #6d8fe6;
  --chart-3: #3a4f7a;
  --chart-4: #34b07a;
  --chart-5: #f0b429;
  --sidebar: #0d0d0d;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #f0f0f0;
  --sidebar-primary-foreground: #000000;
  --sidebar-accent: #313131;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: rgb(255 255 255 / 12%);
  --sidebar-ring: #b1b1b1;
}
